import json
from pathlib import Path
root = Path('products/services/open-software-tenders')
paths = sorted(set(root.glob('**/*deadline*.json')) | set(root.glob('**/*retirement*.json')) | set(root.glob('**/publication-result.json')))
legacy = Path('products/services/open-software-tender/retirement.json')
if legacy.is_file():
    paths.append(legacy)
for path in paths:
    record = json.loads(path.read_text())
    if isinstance(record, dict):
        result = {key: value for key, value in record.items() if any(term in key.lower() for term in ('deadline', 'retir', 'expiry', 'digest', 'status', 'url', 'receipt', 'supersed'))}
        print(json.dumps({'path': str(path), 'fields': result}, ensure_ascii=False))
